def build_all():
    print("开始构建阿拉伯语分级与专业词书数据集...")
    
    a1_a2 = get_a1_a2_data()
    b1_b2 = get_b1_b2_data()
    c1 = get_c1_data()
    
    it = get_it_data()
    biz = get_business_data()
    diplo = get_diplomacy_data()
    med = get_medical_data()
    law = get_law_data()
    idioms = get_idioms_data()
    roots = get_roots_data()
    
    # 写入 levels 目录
    (LEVELS_DIR / 'a1_a2_primary.json').write_text(json.dumps(a1_a2, ensure_ascii=False, indent=2), encoding='utf-8')
    (LEVELS_DIR / 'b1_b2_intermediate.json').write_text(json.dumps(b1_b2, ensure_ascii=False, indent=2), encoding='utf-8')
    (LEVELS_DIR / 'c1_advanced.json').write_text(json.dumps(c1, ensure_ascii=False, indent=2), encoding='utf-8')
    
    # 写入 themed 目录
    (THEMED_DIR / 'it_computing.json').write_text(json.dumps(it, ensure_ascii=False, indent=2), encoding='utf-8')
    (THEMED_DIR / 'business_finance.json').write_text(json.dumps(biz, ensure_ascii=False, indent=2), encoding='utf-8')
    (THEMED_DIR / 'diplomacy_politics.json').write_text(json.dumps(diplo, ensure_ascii=False, indent=2), encoding='utf-8')
    (THEMED_DIR / 'medical_health.json').write_text(json.dumps(med, ensure_ascii=False, indent=2), encoding='utf-8')
    (THEMED_DIR / 'law_judiciary.json').write_text(json.dumps(law, ensure_ascii=False, indent=2), encoding='utf-8')
    (THEMED_DIR / 'idioms_proverbs.json').write_text(json.dumps(idioms, ensure_ascii=False, indent=2), encoding='utf-8')
    (THEMED_DIR / 'roots_derivation.json').write_text(json.dumps(roots, ensure_ascii=False, indent=2), encoding='utf-8')
    
    total = sum(len(x) for x in [a1_a2, b1_b2, c1, it, biz, diplo, med, law, idioms, roots])
    print(f"数据生成完成！共 10 大类别，累计 {total} 个专业词条已落盘。")

if __name__ == '__main__':
    build_all()
